#!/usr/bin/python3
"""Native GTK panel. Generated by the game-trainer skill."""
import fcntl, json, os, sys
from pathlib import Path
import gi
gi.require_version('Gtk', '3.0')
from gi.repository import GLib, Gtk
from memory import Game

ROOT = Path(__file__).resolve().parent
PREFERENCES = ROOT / 'preferences.json'
CONTROLS = {'example': 'Example effect'}  # key: label


def load():
    try:
        saved = json.loads(PREFERENCES.read_text())
        return {k: bool(saved.get(k)) for k in CONTROLS}
    except (OSError, ValueError, AttributeError):
        return {k: False for k in CONTROLS}


def save(selected):
    temp = PREFERENCES.with_suffix('.tmp')
    temp.write_text(json.dumps(selected, indent=2) + '\n')
    os.replace(temp, PREFERENCES)


class Panel(Gtk.Window):
    def __init__(self):
        super().__init__(title=CONFIG_TITLE)
        self.game = None
        self.selected = load()
        self.status = Gtk.Label(label='Waiting for the game', xalign=0)
        box = Gtk.Box(orientation=Gtk.Orientation.VERTICAL, spacing=8, margin=12)
        box.add(self.status)
        self.switches = {}
        for key, label in CONTROLS.items():
            check = Gtk.CheckButton(label=label, active=self.selected[key])
            check.connect('toggled', self.toggled, key)
            box.add(check)
            self.switches[key] = check
        off = Gtk.Button(label='Turn all off')
        off.connect('clicked', self.all_off)
        box.add(off)
        self.add(box)
        self.connect('destroy', self.shutdown)
        GLib.timeout_add(250, self.tick)

    def toggled(self, check, key):
        self.selected[key] = check.get_active()
        save(self.selected)

    def all_off(self, _button):
        for check in self.switches.values():
            check.set_active(False)

    def tick(self):
        try:
            if self.game is None or not self.game.alive():
                self.game = Game()
            if self.game.ready():
                self.status.set_text('Connected')
                self.apply()
            else:
                self.status.set_text('Game found. Load a single-player save.')
        except (OSError, RuntimeError) as error:
            self.game = None
            self.status.set_text(str(error))
        return True

    def apply(self):
        """Re-apply each selected effect, and restore any that was switched off."""

    def shutdown(self, _window):
        # Restore every patch here, because closing the panel disables its effects.
        if self.game:
            self.game.close()
        Gtk.main_quit()


CONFIG_TITLE = json.loads((ROOT / 'config.json').read_text())['title']

if __name__ == '__main__':
    lock = open(ROOT / 'trainer.lock', 'w')
    try:
        fcntl.flock(lock, fcntl.LOCK_EX | fcntl.LOCK_NB)
    except BlockingIOError:
        sys.exit('The trainer is already open.')
    Panel().show_all()
    Gtk.main()
